add_action( 'template_redirect', 'perfectpixel_add_product_on_page_visit' );

function perfectpixel_add_product_on_page_visit() {
	$page_id    = (int) '{{visit_page_id}}';
	$product_id = (int) '{{visit_product_id}}';
	if ( ! $page_id || ! $product_id || ! is_page( $page_id ) || ! function_exists( 'WC' ) || ! WC()->cart ) {
		return;
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( (int) $item['product_id'] === $product_id ) {
			return;
		}
	}
	WC()->cart->add_to_cart( $product_id );
}
